args.command:
node -e 'const f=require("fs"),base="deliverables/",finding=JSON.parse(f.readFileSync("/tmp/route-energy-check"));
const cost=JSON.parse(f.readFileSync(base+"cost-model.json")),line=cost.lines.find(l=>l.site===finding.site);line.freight+=finding.supplement;line.lineTotal=line.unitPrice+line.freight;cost.total=cost.lines.reduce((v,l)=>v+l.lineTotal,0);f.writeFileSync(base+"cost-model.json",JSON.stringify(cost,null,2)+"\n");
let rec=f.readFileSync(base+"recommendation.md","utf8").replaceAll("536,000","543,500").replace("268,000 at Harbor","275,500 at Harbor").replace("18,000 freight = USD 268,000","25,500 freight = USD 275,500").replace('\''"totalUsd": 536000'\'','\''"totalUsd": 543500'\'').replace('\''"sources/quotes.csv",'\'','\''"updates/2026-11-19/hf-freight-amendment.md",\n    "sources/quotes.csv",'\'');f.writeFileSync(base+"recommendation.md",rec);
let risk=f.readFileSync(base+"risk-review.md","utf8").replace("any change to the K-900 price or freight applies to both lines","the USD 7,500 Harbor Flats supplement applies to its consignment only");risk=risk.replaceAll("site-specific logistics are not","other site-specific logistics are not").replace("and any site-specific logistics","and other site-specific logistics");f.writeFileSync(base+"risk-review.md",risk);' && git add deliverables && git commit -qm 'Revise Harbor Flats freight estimate'

